let currentLang = 'es';
window.getCurrentLang = function(){ return currentLang; };
function t(key){ return translations[currentLang][key] || translations['es'][key] || ''; }

function statusLabel(s){
  const labels = {
    es:{legal:'Legal total', medicinal:'Medicinal', illegal:'Ilegal'},
    en:{legal:'Fully legal', medicinal:'Medicinal', illegal:'Illegal'},
    de:{legal:'Vollständig legal', medicinal:'Medizinisch', illegal:'Illegal'},
    fr:{legal:'Totalement légal', medicinal:'Médical', illegal:'Illégal'}
  };
  return labels[currentLang][s];
}

const grid = document.getElementById('countryGrid');
function renderGrid(filter){
  grid.innerHTML = '';
  const filtered = countries.filter(c => filter==='all' || c.status===filter);
  filtered.forEach((c,i)=>{
    if(!isPremium && i>=3) return;
    const el = document.createElement('div');
    el.className = 'country-card';
    el.style.setProperty('--status-color', c.color);
    el.onclick = () => showDetail(c);
    el.innerHTML = `
      <div class="top">
        <div><h4>${flagImg(c.flag)} ${c.name}</h4><div class="region">${regionNames[c.region][currentLang]}</div></div>
        <div class="badge">${statusLabel(c.status)}</div>
      </div>
      <div class="desc">${c.desc[currentLang] || c.desc.es}</div>`;
    grid.appendChild(el);
  });
  if(!isPremium && filtered.length>3){
    const teaser = document.createElement('div');
    teaser.className = 'teaser-card';
    teaser.innerHTML = `${LOCK_SVG}<h4>${t('legalTeaserVisto')} 3 ${t('legalTeaserDe')} ${filtered.length}</h4><p>${t('legalTeaserDesbloquea')}</p>`;
    grid.appendChild(teaser);
  }
}
document.querySelectorAll('.chip').forEach(chip=>{
  chip.onclick = ()=>{
    document.querySelectorAll('.chip').forEach(c=>c.classList.remove('on'));
    chip.classList.add('on');
    renderGrid(chip.dataset.f);
    renderLegalMap();
  };
});

let currentDetailCountry = null;
function goToCountry(name){
  const c = countries.find(function(c){ return c.name === name; });
  if(c) showDetail(c);
}
function showDetail(c){
  currentDetailCountry = c;
  const el = document.getElementById('detailContent');
  el.innerHTML = `
    <div class="detail-head">
      <div class="big-stamp" style="--status-color:${c.color}; color:${c.color};"><div style="font-family:'Manrope',sans-serif; font-style:italic; font-size:15px;">${c.name}</div><span>${statusLabel(c.status)}</span></div>
      <div>
        <h2>${flagImg(c.flag, 28)} ${c.name}</h2>
        <div class="status-line" style="color:${c.color}">${statusLabel(c.status)} · ${regionNames[c.region][currentLang]}</div>
      </div>
    </div>
    <div class="detail-grid">
      <div>
        <div class="card-block"><h3>${t('detailEstado')}</h3><p>${c.desc[currentLang] || c.desc.es}</p><div class="note-box">${t('detailNote')}</div></div>
        <div class="card-block"><h3>${t('detailTimeline')}</h3><div class="timeline">${c.history.map(h=>`<div class="tl-item"><div class="yr">${h[0]}</div><div class="tx">${h[1][currentLang] || h[1].es}</div></div>`).join('')}</div></div>
      </div>
      <div>
        <div class="card-block"><h3>${t('detailTraveler')}</h3><p>${c.portar[currentLang] || c.portar.es}</p></div>
        <div class="card-block"><h3>${t('detailSources')}</h3>${c.sources.map(s=>{
          const label = typeof s === 'string' ? s : s.label;
          const link = (typeof s === 'object' && s.url && isPremium) ? ` <a href="${s.url}" target="_blank" rel="noopener noreferrer" style="color:var(--teal); font-weight:600;">→</a>` : '';
          return `<div class="source-tag"><div class="source-dot"></div>${label}${link}</div>`;
        }).join('')}</div>
      </div>
    </div>`;
  showScreen('detail');
}

function applyLang(){
  document.documentElement.lang = currentLang;
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key = el.getAttribute('data-i18n');
    if(translations[currentLang][key] !== undefined) el.innerHTML = translations[currentLang][key];
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{
    const key = el.getAttribute('data-i18n-ph');
    if(translations[currentLang][key] !== undefined) el.setAttribute('placeholder', translations[currentLang][key]);
  });
  if(document.getElementById('harvestChecklist')) renderHarvestChecklist();
  if(document.getElementById('glosarioList')) renderGlosario(document.getElementById('glSearchInput')?.value || '');
  if(comparadorOpen && isPremium) renderComparador();
  if(document.getElementById('vpdTemp')){ updateVPD(); updateDLI(); updateDose(); }
  if(document.getElementById('cmDoseMg')) updateDoseComestibles();
  if(document.getElementById('cmDecarbGramos')) updateDecarbCalc();
  if(document.getElementById('snCalcTotal')) updateSnCalc();
  if(document.getElementById('ilLuzArea')) updateIlCalcLuz();
  if(document.getElementById('degradTiempo')) updateDegradCalc();
  if(document.getElementById('ecpValor')) updateEcp();
  if(document.getElementById('luxValor')) updateLux();
  if(document.getElementById('yldModo')) updateYld();
  if(document.getElementById('subForma')) updateSub();
  if(document.getElementById('secFecha')) updateSec();
  if(document.getElementById('cncTipo')) updateCnc();
  if(document.getElementById('hvwTipo')) updateHvw();
  if(document.getElementById('cbnTiempo')) updateCbnDegrad();
  if(document.getElementById('coaPest')) updateCoaTool();
  if(document.getElementById('ciTipo')) updateCostoInicial();
  updateTplLinks();
  applySourceLinks();
  if(currentDetailCountry && document.getElementById('detail')?.classList.contains('active')) showDetail(currentDetailCountry);
  renderGrid(document.querySelector('.chip.on')?.dataset.f || 'all');
  applyTier();
}
document.querySelectorAll('#langSwitch button').forEach(b=>{
  b.onclick = ()=>{
    currentLang = b.dataset.lang;
    document.querySelectorAll('#langSwitch button').forEach(x=>x.classList.remove('lang-on'));
    b.classList.add('lang-on');
    applyLang();
  };
});

function showScreen(id){
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  document.querySelectorAll('nav.tabs button').forEach(b=>b.classList.remove('active'));
  const navBtn = document.querySelector(`nav.tabs button[data-screen="${id}"]`);
  if(navBtn) navBtn.classList.add('active');
  if(id === 'bitacora') loadBitEntries();
  if(id === 'cuenta') renderCuenta();
  if(id === 'glosario') renderGlosario('');
  if(id === 'comunidad') renderComunidadScreen();
  if(id === 'legal') renderLegalMap();
  window.scrollTo(0,0);
}
document.querySelectorAll('nav.tabs button').forEach(b=>{
  b.onclick = ()=> showScreen(b.dataset.screen);
});

function renderGlosario(query){
  const el = document.getElementById('glosarioList');
  if(!el) return;
  const q = (query||'').toLowerCase().trim();
  const filtered = glossary.filter(g=>{
    const termText = (g.term[currentLang]||g.term.es).toLowerCase();
    const defText = (g.def[currentLang]||g.def.es).toLowerCase();
    return !q || termText.includes(q) || defText.includes(q);
  });
  if(filtered.length === 0){
    el.innerHTML = `<p class="subhead">${t('glSinResultados')}</p>`;
    return;
  }
  el.innerHTML = filtered.map(g=>`
    <div class="card-block" style="padding:14px 18px;">
      <h4 style="margin:0 0 6px; font-family:'Manrope',sans-serif; font-size:15px; color:var(--moss-deep);">${g.term[currentLang]||g.term.es}</h4>
      <p style="margin:0; font-size:13px; color:var(--ink-soft);">${g.def[currentLang]||g.def.es}</p>
    </div>`).join('');
}

function showSub(screen, sub){
  showScreen(screen);
  document.querySelectorAll('#'+screen+' .subview').forEach(v=>v.classList.remove('active'));
  document.getElementById(screen+'-'+sub).classList.add('active');
  document.querySelectorAll('#'+screen+' .sub-pill').forEach(p=>p.classList.remove('on'));
  document.querySelector('#'+screen+' .sub-pill[data-sub="'+sub+'"]').classList.add('on');
  if(screen==='cultivo' && sub==='cosecha') renderHarvestChecklist();
  if(screen==='cultivo' && sub==='diagnostico') renderSymptomPicker();
  window.scrollTo(0,0);
}

