function applySourceLinks(){
  document.querySelectorAll('.source-link-premium').forEach(el => el.remove());
  if(!isPremium) return;
  Object.keys(sourceLinks).forEach(key => {
    document.querySelectorAll(`[data-i18n="${key}"]`).forEach(el => {
      const a = document.createElement('a');
      a.className = 'source-link-premium';
      a.href = sourceLinks[key];
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      a.textContent = '🔗 ' + t('verEstudioOriginal');
      a.style.cssText = 'display:inline-block; margin-top:8px; font-family:IBM Plex Mono,monospace; font-size:10.5px; color:var(--teal); text-decoration:none; border-bottom:1px dotted var(--teal);';
      el.insertAdjacentElement('afterend', a);
    });
  });
}
function applyTier(){
  FULL_GATES.forEach(g => setFullGate(document.getElementById(g.id), !isPremium));
  gateGrid(document.getElementById('diagGrid'), '.diag-card', 2, 'gtDiagTeaserTitle', 'gtDiagTeaserDesc');
  gateGrid(document.getElementById('ciencia-papers'), '.paper-card', 1, 'gtPapersTeaserTitle', 'gtPapersTeaserDesc');
  gateGrid(document.getElementById('minorCannabinoidGrid'), '.specimen', 2, 'gtCannaTeaserTitle', 'gtCannaTeaserDesc');
  gateGrid(document.getElementById('terpeneGrid'), '.specimen', 2, 'gtTerpTeaserTitle', 'gtTerpTeaserDesc');
  gateGrid(document.getElementById('flavonoidGrid'), '.specimen', 2, 'gtFlavTeaserTitle', 'gtFlavTeaserDesc');
  gateGrid(document.getElementById('ciencia-mitos'), '.myth-row', 2, 'gtMitosTeaserTitle', 'gtMitosTeaserDesc');
  document.querySelectorAll('.ad-slot').forEach(a => a.style.display = isPremium ? 'none' : 'block');
  document.querySelectorAll('.tb-btn .mini-lock').forEach(l => l.style.display = isPremium ? 'none' : 'inline-flex');
  applySourceLinks();
  renderCultivars(document.querySelector('.chip[data-cf].on')?.dataset.cf || 'all');
  if(document.getElementById('cuenta')?.classList.contains('active')) renderCuenta();
  if(currentDetailCountry && document.getElementById('detail')?.classList.contains('active')) showDetail(currentDetailCountry);
  renderBitacoraGate();
  renderGrid(document.querySelector('.chip.on')?.dataset.f || 'all');
}

document.querySelectorAll('#tierSwitch button').forEach(b=>{
  b.onclick = ()=>{
    isPremium = (b.dataset.tier === 'premium');
    document.querySelectorAll('#tierSwitch button').forEach(x=>x.classList.remove('tier-on'));
    b.classList.add('tier-on');
    applyTier();
  };
});
applyTier();

/* ===================== PREMIUM MODAL ===================== */
function openPremium(){ document.getElementById('premiumModal').classList.add('active'); }
function closePremium(){ document.getElementById('premiumModal').classList.remove('active'); }

/* ===================== ESPACIO PUBLICITARIO (formulario de contacto) ===================== */
function openAdInquiry(){ document.getElementById('adInquiryModal').classList.add('active'); }
function closeAdInquiry(){ document.getElementById('adInquiryModal').classList.remove('active'); }
document.getElementById('adInquiryForm')?.addEventListener('submit', async (e) => {
  e.preventDefault();
  const btn = document.getElementById('adInquirySubmitBtn');
  const msgEl = document.getElementById('adInquiryMsg');
  const honeypot = document.querySelector('#adInquiryForm input[name="_hp"]').value;
  const payload = {
    honeypot,
    nombre: document.getElementById('adInquiryNombre').value.trim(),
    empresa: document.getElementById('adInquiryEmpresa').value.trim(),
    correo: document.getElementById('adInquiryCorreo').value.trim(),
    mensaje: document.getElementById('adInquiryMensaje').value.trim(),
    lang: currentLang
  };
  btn.disabled = true;
  msgEl.style.color = 'var(--ink-soft)';
  msgEl.textContent = t('adInquiryEnviando');
  try{
    const res = await fetch('/api/ad-inquiry', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    if(!res.ok) throw new Error('request failed');
    msgEl.style.color = 'var(--moss-deep)';
    msgEl.textContent = t('adInquiryOk');
    document.getElementById('adInquiryForm').reset();
    setTimeout(closeAdInquiry, 2500);
  }catch(err){
    msgEl.style.color = 'var(--clay)';
    msgEl.textContent = t('adInquiryError');
  }finally{
    btn.disabled = false;
  }
});

