// Prefill the join form from the current user's existing directory row, if any,
// so "Unirme" doubles as "edit my entry".
async function prefillCommunityJoinForm(){
  if(!window.mvCommunity || !window.mvCurrentUser) return;
  const nameEl = document.getElementById('cmyNombreInput');
  const paisEl = document.getElementById('cmyPaisInput');
  const tipoEl = document.getElementById('cmyTipoInput');
  if(!nameEl) return;
  let mine = null;
  try{ mine = await window.mvCommunity.getMyMemberProfile(); }catch(e){ return; }
  if(!mine) return;
  if(document.activeElement !== nameEl) nameEl.value = mine.display_name || '';
  if(paisEl && mine.country) paisEl.value = mine.country;
  if(tipoEl && mine.profile_type) tipoEl.value = mine.profile_type;
  const btnEl = document.querySelector('#comunidad button[onclick="joinCommunity()"]');
  if(btnEl) btnEl.textContent = t('cmyActualizarBtn');
}
async function joinCommunity(){
  const nameEl = document.getElementById('cmyNombreInput');
  const correoEl = document.getElementById('cmyCorreoInput');
  const paisEl = document.getElementById('cmyPaisInput');
  const tipoEl = document.getElementById('cmyTipoInput');
  const msgEl = document.getElementById('cmyJoinMsg');
  const name = nameEl.value.trim();
  if(!name){ nameEl.focus(); return; }
  if(!window.mvCurrentUser){
    msgEl.textContent = t('cmyJoinNeedsAccount');
    msgEl.style.color = 'var(--clay)';
    msgEl.style.display = 'block';
    return;
  }
  try{
    await window.mvCommunity.upsertMyMemberProfile({
      display_name: name.slice(0,30),
      country: paisEl.value,
      profile_type: tipoEl.value,
    });
    const correo = correoEl.value.trim();
    if(correo){
      await window.mvSupabase.from('profiles').update({ contact_email: correo }).eq('id', window.mvCurrentUser.id);
    }
  }catch(e){
    msgEl.textContent = t('authErrGeneric');
    msgEl.style.color = 'var(--clay)';
    msgEl.style.display = 'block';
    return;
  }
  correoEl.value = '';
  msgEl.textContent = t('cmyJoinExito');
  msgEl.style.color = 'var(--moss-deep)';
  msgEl.style.display = 'block';
  setTimeout(()=>{ msgEl.style.display = 'none'; }, 4000);
  renderComunidadScreen();
}
function runSearch(){
  const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const q = norm(document.getElementById('searchInput').value.trim().toLowerCase());
  const resultsEl = document.getElementById('searchResults');
  if(q.length < 2){ resultsEl.innerHTML = ''; return; }
  const index = buildSearchIndex();
  const matches = index.filter(item => norm(item.title.toLowerCase()).includes(q) || (item.cat && norm(item.cat.toLowerCase()).includes(q))).slice(0,20);
  if(matches.length===0){
    resultsEl.innerHTML = '<div class="search-empty">Sin resultados para "'+q+'"</div>';
    return;
  }
  resultsEl.innerHTML = matches.map((m,i)=>`
    <div class="search-result" data-idx="${i}">
      <span class="search-result-title">${m.title}</span>
      <span class="search-result-cat">${m.cat}</span>
    </div>`).join('');
  resultsEl.querySelectorAll('.search-result').forEach((row,i)=>{
    row.onclick = ()=>{
      const m = matches[i];
      closeSearch();
      showScreen(m.screen);
      if(m.sub) setTimeout(()=> showSub(m.screen, m.sub), 50);
      if(m.countryRef){
        const c = countries.find(x=>x.name===m.countryRef);
        if(c) setTimeout(()=> showDetail(c), 50);
      }
    };
  });
}
document.getElementById('searchOpenBtn')?.addEventListener('click', openSearch);
document.getElementById('searchInput')?.addEventListener('input', runSearch);
document.getElementById('searchModal')?.addEventListener('click', (e)=>{ if(e.target.id==='searchModal') closeSearch(); });
document.addEventListener('keydown', (e)=>{
  if(e.key==='Escape') closeSearch();
  if((e.ctrlKey||e.metaKey) && e.key==='k'){ e.preventDefault(); openSearch(); }
});
document.getElementById('premiumModal').addEventListener('click', (e)=>{
  if(e.target.id === 'premiumModal') closePremium();
});
document.addEventListener('click', (e)=>{
  if(e.target.classList && e.target.classList.contains('gate-btn')) openPremium();
});
document.querySelectorAll('.tb-btn').forEach(btn=>{
  btn.style.cursor = 'pointer';
  btn.onclick = ()=>{
    if(!isPremium){ openPremium(); return; }
    const panelId = btn.dataset.panel;
    document.querySelectorAll('.travel-panel').forEach(p=>{
      if(p.id === panelId) p.classList.toggle('active');
      else p.classList.remove('active');
    });
    if(panelId === 'tp-checklist') renderTravelChecklist();
  };
});

/* ===================== VARIEDADES ===================== */
function buildLineageTree(parents, childName){
  const n = parents.length;
  const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;');
  if(n === 1){
    return `<svg viewBox="0 0 180 66" width="100%" height="58" style="max-width:210px; display:block; margin:8px auto 0;">
      <rect x="50" y="2" width="80" height="22" rx="4" fill="none" stroke="var(--ink-soft)" stroke-width="1.2"/>
      <text x="90" y="17" text-anchor="middle" font-size="8" font-family="IBM Plex Mono, monospace" fill="var(--ink)">${esc(parents[0])}</text>
      <line x1="90" y1="24" x2="90" y2="40" stroke="var(--ink-soft)" stroke-width="1.2"/>
      <rect x="45" y="42" width="90" height="22" rx="4" fill="var(--moss)" opacity="0.15" stroke="var(--moss-deep)" stroke-width="1.4"/>
      <text x="90" y="57" text-anchor="middle" font-size="8" font-weight="600" font-family="IBM Plex Mono, monospace" fill="var(--moss-deep)">${esc(childName)}</text>
    </svg>`;
  }
  const width = n === 2 ? 200 : 270;
  const positions = n === 2 ? [40,160] : [40,135,230];
  const boxW = n === 2 ? 80 : 78;
  const boxes = parents.map((p,i) => `
    <rect x="${positions[i]-boxW/2}" y="2" width="${boxW}" height="22" rx="4" fill="none" stroke="var(--ink-soft)" stroke-width="1.1"/>
    <text x="${positions[i]}" y="17" text-anchor="middle" font-size="7.5" font-family="IBM Plex Mono, monospace" fill="var(--ink)">${esc(p)}</text>
    <line x1="${positions[i]}" y1="24" x2="${width/2}" y2="40" stroke="var(--ink-soft)" stroke-width="1"/>`).join('');
  return `<svg viewBox="0 0 ${width} 66" width="100%" height="58" style="max-width:${width+10}px; display:block; margin:8px auto 0;">
    ${boxes}
    <rect x="${width/2-45}" y="42" width="90" height="22" rx="4" fill="var(--moss)" opacity="0.15" stroke="var(--moss-deep)" stroke-width="1.4"/>
    <text x="${width/2}" y="57" text-anchor="middle" font-size="8" font-weight="600" font-family="IBM Plex Mono, monospace" fill="var(--moss-deep)">${esc(childName)}</text>
  </svg>`;
}
function renderCultivars(filter){
  if(!cvGrid) return;
  cvGrid.innerHTML = '';
  const list = cultivars.filter(c => filter==='all' || c.quimiotipo===filter);
  const visible = isPremium ? list : list.slice(0,3);
  visible.forEach(c=>{
    const el = document.createElement('div');
    el.className = 'specimen';
    el.innerHTML = `<h4>${c.name}</h4><div class="sci">${c.tipo[currentLang] || c.tipo.es} — ${t('vrTipoPrefix')} ${c.quimiotipo}</div>
      <div class="spec-row"><span>THC</span><span>${c.thc}</span></div>
      <div class="spec-row"><span>CBD</span><span>${c.cbd}</span></div>
      <div class="spec-row"><span>${t('vrFloracion')}</span><span>${c.floracion[currentLang] || c.floracion.es}</span></div>
      <div class="spec-row"><span>${t('vrLinaje')}</span><span>${c.linaje[currentLang] || c.linaje.es}</span></div>
      <div class="spec-row"><span>${t('vrTerpenos')}</span><span>${c.terpenos[currentLang] || c.terpenos.es}</span></div>
      <div class="spec-row"><span>${t('vrDificultad')}</span><span>${c.dificultad[currentLang] || c.dificultad.es}</span></div>
      ${c.parents ? buildLineageTree(c.parents, c.name) : ''}`;
    cvGrid.appendChild(el);
  });
  if(!isPremium && list.length>3){
    const teaser = document.createElement('div');
    teaser.className = 'teaser-card';
    teaser.innerHTML = `${LOCK_SVG}<h4>${t('vrVisteTeaser')} 3 ${t('vrDe')} ${list.length}</h4><p>${t('vrDesbloquea')}</p>`;
    cvGrid.appendChild(teaser);
  }
}

let comparadorOpen = false;
function toggleComparador(){
  if(!isPremium){
    const panel = document.getElementById('comparadorPanel');
    panel.style.display = 'block';
    panel.innerHTML = `<div class="note-box">${LOCK_SVG} ${t('cpLockedMsg')}</div>`;
    comparadorOpen = true;
    return;
  }
  comparadorOpen = !comparadorOpen;
  const panel = document.getElementById('comparadorPanel');
  panel.innerHTML = `<div style="display:flex; gap:12px; margin-bottom:16px; flex-wrap:wrap;">
      <select id="cpSelectA" class="cp-select" onchange="renderComparador()"></select>
      <select id="cpSelectB" class="cp-select" onchange="renderComparador()"></select>
    </div>
    <div id="comparadorTable"></div>`;
  panel.style.display = comparadorOpen ? 'block' : 'none';
  if(comparadorOpen){
    populateComparadorSelects();
    renderComparador();
  }
}
function populateComparadorSelects(){
  const selA = document.getElementById('cpSelectA');
  const selB = document.getElementById('cpSelectB');
  const prevA = selA.value, prevB = selB.value;
  const opts = cultivars.map((c,i)=>`<option value="${i}">${c.name}</option>`).join('');
  selA.innerHTML = opts;
  selB.innerHTML = opts;
  selA.value = prevA || '0';
  selB.value = prevB || '1';
}
function renderComparador(){
  const el = document.getElementById('comparadorTable');
  if(!el) return;
  const a = cultivars[document.getElementById('cpSelectA').value || 0];
  const b = cultivars[document.getElementById('cpSelectB').value || 1];
  const rows = [
    [t('vrTipoPrefix'), `${t('vrTipoPrefix')} ${a.quimiotipo}`, `${t('vrTipoPrefix')} ${b.quimiotipo}`],
    ['THC', a.thc, b.thc],
    ['CBD', a.cbd, b.cbd],
    [t('vrFloracion'), a.floracion[currentLang]||a.floracion.es, b.floracion[currentLang]||b.floracion.es],
    [t('vrDificultad'), a.dificultad[currentLang]||a.dificultad.es, b.dificultad[currentLang]||b.dificultad.es],
    [t('vrTerpenos'), a.terpenos[currentLang]||a.terpenos.es, b.terpenos[currentLang]||b.terpenos.es],
    [t('vrLinaje'), a.linaje[currentLang]||a.linaje.es, b.linaje[currentLang]||b.linaje.es],
  ];
  el.innerHTML = `<div class="cp-table">
    <div class="cp-row cp-header"><span>—</span><span>${a.name}</span><span>${b.name}</span></div>
    ${rows.map(r=>`<div class="cp-row"><span>${r[0]}</span><span>${r[1]}</span><span>${r[2]}</span></div>`).join('')}
  </div>`;
}
document.querySelectorAll('.chip[data-cf]').forEach(chip=>{
  chip.onclick = ()=>{
    document.querySelectorAll('.chip[data-cf]').forEach(c=>c.classList.remove('on'));
    chip.classList.add('on');
    renderCultivars(chip.dataset.cf);
  };
});

/* ===================== CALCULADORAS ===================== */
function svp(t){ return 0.6108 * Math.exp(17.27*t/(t+237.3)); }
function updateVPD(){
  const t = parseFloat(document.getElementById('vpdTemp').value) || 0;
  const rh = parseFloat(document.getElementById('vpdRH').value) || 0;
  const leafOffset = -2;
  const leafT = t + leafOffset;
  const vpd = svp(leafT) - (rh/100)*svp(t);
  const target = parseFloat(document.getElementById('vpdStage').value);
  document.getElementById('vpdResult').textContent = vpd.toFixed(2) + ' kPa';
  const diff = Math.abs(vpd - target);
  const verdictEl = document.getElementById('vpdVerdict');
  if(diff < 0.15){ verdictEl.textContent = '✓ Dentro del rango objetivo'; verdictEl.style.color = 'var(--moss-deep)'; }
  else { verdictEl.textContent = vpd > target ? '⚠ Más alto que el objetivo — ambiente muy seco' : '⚠ Más bajo que el objetivo — ambiente muy húmedo'; verdictEl.style.color = 'var(--resin)'; }
}
function updateDLI(){
  const ppfd = parseFloat(document.getElementById('dliPPFD').value) || 0;
  const hours = parseFloat(document.getElementById('dliHours').value) || 0;
  const dli = ppfd * hours * 0.0036;
  document.getElementById('dliResult').textContent = dli.toFixed(1) + ' mol/m²/día';
}
function updateDose(){
  const mg = parseFloat(document.getElementById('doseMg').value) || 0;
  const servings = parseFloat(document.getElementById('doseServings').value) || 1;
  const dose = mg / servings;
  document.getElementById('doseResult').textContent = dose.toFixed(1) + ' mg / porción';
}
function updateDoseComestibles(){
  const mgEl = document.getElementById('cmDoseMg');
  const servingsEl = document.getElementById('cmDoseServings');
  const resultEl = document.getElementById('cmDoseResult');
  if(!mgEl || !servingsEl || !resultEl) return;
  const mg = parseFloat(mgEl.value) || 0;
  const servings = parseFloat(servingsEl.value) || 1;
  const dose = mg / servings;
  resultEl.textContent = dose.toFixed(1) + ' mg / porción';
}
function updateDecarbCalc(){
  const gramosEl = document.getElementById('cmDecarbGramos');
  const pctEl = document.getElementById('cmDecarbPct');
  const resultEl = document.getElementById('cmDecarbResult');
  if(!gramosEl || !pctEl || !resultEl) return;
  const gramos = parseFloat(gramosEl.value) || 0;
  const pct = parseFloat(pctEl.value) || 0;
  const mgThca = gramos * 1000 * (pct / 100);
  const mgThc = mgThca * 0.877;
  resultEl.textContent = mgThc.toFixed(0) + ' mg de THC';
}
['cmDecarbGramos','cmDecarbPct'].forEach(id=>{
  const el = document.getElementById(id);
  if(el) el.addEventListener('input', updateDecarbCalc);
});
if(document.getElementById('cmDecarbGramos')) updateDecarbCalc();
function updateSnCalc(){
  const totalEl = document.getElementById('snCalcTotal');
  const resultEl = document.getElementById('snCalcResult');
  if(!totalEl || !resultEl) return;
  const total = parseFloat(totalEl.value) || 0;
  const parte = total / 7;
  const ingredientes = [
    {label: t('snCalcIng1'), partes: 4},
    {label: t('snCalcIng2'), partes: 1},
    {label: t('snCalcIng3'), partes: 1},
    {label: t('snCalcIng4'), partes: 1},
  ];
  resultEl.innerHTML = ingredientes.map(ing => `<div style="display:flex; justify-content:space-between;"><span>${ing.label}</span><span style="color:var(--moss-deep); font-weight:600;">${(parte*ing.partes).toFixed(2)}</span></div>`).join('');
}
['snCalcTotal'].forEach(id=>{
  const el = document.getElementById(id);
  if(el) el.addEventListener('input', updateSnCalc);
});
if(document.getElementById('snCalcTotal')) updateSnCalc();
const IL_LUZ_PPE = { LED:2.7, HPS:1.3, CMH:1.8 };
function updateIlCalcLuz(){
  const areaEl = document.getElementById('ilLuzArea');
  const ppfdEl = document.getElementById('ilLuzPPFD');
  const tipoEl = document.getElementById('ilLuzTipo');
  const horasEl = document.getElementById('ilLuzHoras');
  const precioEl = document.getElementById('ilLuzPrecio');
  const resultEl = document.getElementById('ilLuzResult');
  const costoWrap = document.getElementById('ilLuzCostoWrap');
  const costoResultEl = document.getElementById('ilLuzCostoResult');
  if(!areaEl || !resultEl) return;
  const area = parseFloat(areaEl.value) || 0;
  const ppfd = parseFloat(ppfdEl.value) || 0;
  const ppe = parseFloat(tipoEl.value) || 2.7;
  const horas = parseFloat(horasEl.value) || 0;
  const ppfTotal = ppfd * area;
  const watts = ppe > 0 ? ppfTotal / ppe : 0;
  const dli = ppfd * horas * 0.0036;
  resultEl.innerHTML = `
    <div style="display:flex; justify-content:space-between;"><span>${t('ilLuzResPpf')}</span><span style="color:var(--moss-deep); font-weight:600;">${ppfTotal.toFixed(0)} μmol/s</span></div>
    <div style="display:flex; justify-content:space-between;"><span>${t('ilLuzResWatts')}</span><span style="color:var(--moss-deep); font-weight:600;">${watts.toFixed(0)} W</span></div>
    <div style="display:flex; justify-content:space-between;"><span>${t('ilLuzResDli')}</span><span style="color:var(--moss-deep); font-weight:600;">${dli.toFixed(1)} mol/m²/día</span></div>
  `;
  const precio = parseFloat(precioEl?.value) || 0;
  if(precio > 0 && costoWrap && costoResultEl){
    costoWrap.style.display = '';
    costoResultEl.innerHTML = Object.entries(IL_LUZ_PPE).map(([label, tech_ppe]) => {
      const techWatts = tech_ppe > 0 ? ppfTotal / tech_ppe : 0;
      const monthlyKwh = techWatts * horas * 30 / 1000;
      const monthlyCost = monthlyKwh * precio;
      return `<div style="display:flex; justify-content:space-between;"><span>${label} (${techWatts.toFixed(0)}W)</span><span style="color:var(--moss-deep); font-weight:600;">${monthlyKwh.toFixed(0)} kWh — $${monthlyCost.toFixed(2)}/${t('ilLuzMesAbrev')}</span></div>`;
    }).join('');
  } else if(costoWrap){
    costoWrap.style.display = 'none';
  }
}
['ilLuzArea','ilLuzPPFD','ilLuzTipo','ilLuzHoras','ilLuzPrecio'].forEach(id=>{
  const el = document.getElementById(id);
  if(el){ el.addEventListener('input', updateIlCalcLuz); el.addEventListener('change', updateIlCalcLuz); }
});
if(document.getElementById('ilLuzArea')) updateIlCalcLuz();
const DEGRAD_TIME_LEVEL = { weeks:0.5, months:1, '1-2y':2, '3-4y':3.5, '4y+':5 };
const DEGRAD_COND_FACTOR = { 'light-room':1.5, 'dark-room':1.0, fridge:0.5, freezer:0.25 };
function updateDegradCalc(){
  const tiempoEl = document.getElementById('degradTiempo');
  const condEl = document.getElementById('degradCond');
  const resultEl = document.getElementById('degradResult');
  if(!tiempoEl || !resultEl) return;
  const score = (DEGRAD_TIME_LEVEL[tiempoEl.value]||0) * (DEGRAD_COND_FACTOR[condEl.value]||1);
  let level, color, msgKey;
  if(score < 1.5){ level = t('degradRiesgoBajo'); color = 'var(--moss-deep)'; msgKey = 'degradMsgBajo'; }
  else if(score < 3.5){ level = t('degradRiesgoMedio'); color = 'var(--resin)'; msgKey = 'degradMsgMedio'; }
  else { level = t('degradRiesgoAlto'); color = 'var(--clay)'; msgKey = 'degradMsgAlto'; }
  resultEl.innerHTML = `
    <div style="font-family:'Manrope',sans-serif; font-size:22px; font-weight:500; color:${color};">${level}</div>
    <p style="font-size:12.5px; color:var(--ink-soft); margin-top:6px;">${t(msgKey)}</p>
  `;
}
['degradTiempo','degradCond'].forEach(id=>{
  const el = document.getElementById(id);
  if(el){ el.addEventListener('input', updateDegradCalc); el.addEventListener('change', updateDegradCalc); }
});
