/* ===================== DEGRADACIÓN THC → CBN (% estimado) ===================== */
/* Curva base: Ross & ElSohly (1997), UN Bulletin on Narcotics — % de THC degradado
   en muestras almacenadas a temperatura ambiente, interpolación lineal por tramos
   entre los puntos publicados (0,0)(1,16.6)(2,26.8)(3,34.5)(4,41.4); más allá del
   año 4 se extrapola linealmente con la pendiente del último tramo (6.9%/año).
   Los factores por condición son ajustes direccionales aproximados (no constantes
   cinéticas publicadas) consistentes con el patrón confirmado en Zamengo et al.
   (2019): la luz y el calor aceleran la degradación; frío y oscuridad la retrasan. */
const CBN_COND_FACTOR = { 'luz-ambiente':1.00, 'oscuridad-ambiente':0.70, 'refrigerado':0.35, 'congelado':0.15 };
function cbnBaseCurveYears(years){
  const pts = [[0,0],[1,16.6],[2,26.8],[3,34.5],[4,41.4]];
  if(years <= 0) return 0;
  if(years >= 4){
    const slope = pts[4][1] - pts[3][1];
    return Math.min(100, pts[4][1] + slope * (years - 4));
  }
  for(let i=0;i<pts.length-1;i++){
    const [y0,p0] = pts[i], [y1,p1] = pts[i+1];
    if(years >= y0 && years <= y1) return p0 + (p1-p0) * (years-y0)/(y1-y0);
  }
  return 0;
}
function updateCbnDegrad(){
  const tiempoEl = document.getElementById('cbnTiempo');
  const unidadEl = document.getElementById('cbnUnidad');
  const condEl = document.getElementById('cbnCond');
  const resultEl = document.getElementById('cbnResult');
  if(!tiempoEl || !resultEl) return;
  const val = parseFloat(tiempoEl.value) || 0;
  const years = unidadEl.value === 'meses' ? val/12 : val;
  const base = cbnBaseCurveYears(years);
  const factor = CBN_COND_FACTOR[condEl.value] ?? 1;
  const pct = Math.min(100, Math.max(0, base * factor));
  resultEl.innerHTML = `
    <div style="font-family:'Manrope',sans-serif; font-size:32px; font-weight:600; color:var(--moss-deep);">≈ ${pct.toFixed(1)}%</div>
    <p style="font-size:12.5px; color:var(--ink-soft); margin-top:4px;">${t('cbnResultLabel')}</p>
  `;
}
['cbnTiempo','cbnUnidad','cbnCond'].forEach(id=>{
  const el = document.getElementById(id);
  if(el){ el.addEventListener('input', updateCbnDegrad); el.addEventListener('change', updateCbnDegrad); }
});
if(document.getElementById('cbnTiempo')) updateCbnDegrad();

/* ===================== CHECKLIST DE ETIQUETADO (persistido en localStorage del navegador) ===================== */
(function initEtiquetadoChecklist(){
  const ids = ['etChk1','etChk2','etChk3','etChk4','etChk5','etChk6','etChk7','etChk8','etChk9','etChk10','etChk11'];
  ids.forEach(id => {
    const el = document.getElementById(id);
    if(!el) return;
    try{
      if(localStorage.getItem('mv-checklist-'+id) === 'true') el.checked = true;
    }catch(e){}
    el.addEventListener('change', () => {
      try{ localStorage.setItem('mv-checklist-'+id, el.checked); }catch(e){}
    });
  });
})();

/* ===================== CÓMO LEER TU COA (interpretación educativa, sin procesar PDFs) ===================== */
const COA_CONT_FIELDS = ['coaPest','coaMetales','coaMicotox','coaSolv','coaMicrob'];
const COA_CONT_LABELS = { coaPest:'coaLabelPest', coaMetales:'coaLabelMetales', coaMicotox:'coaLabelMicotox', coaSolv:'coaLabelSolv', coaMicrob:'coaLabelMicrob' };
function updateCoaTool(){
  const thcEl = document.getElementById('coaThc');
  const resultEl = document.getElementById('coaToolResult');
  if(!thcEl || !resultEl) return;
  let html = '';
  const thc = thcEl.value;
  const cbdEl = document.getElementById('coaCbd');
  const cbd = cbdEl ? cbdEl.value : '';
  if(thc !== '' || cbd !== ''){
    html += `<div style="background:var(--paper-raised); border-radius:6px; padding:12px 16px;">`;
    if(thc !== '') html += `<div style="display:flex; justify-content:space-between;"><b>${t('coaThcLabel')}</b><span style="color:var(--moss-deep); font-weight:600;">${parseFloat(thc).toFixed(1)}%</span></div>`;
    if(cbd !== '') html += `<div style="display:flex; justify-content:space-between; margin-top:4px;"><b>${t('coaCbdLabel')}</b><span style="color:var(--moss-deep); font-weight:600;">${parseFloat(cbd).toFixed(1)}%</span></div>`;
    html += `<p style="font-size:12.5px; color:var(--ink-soft); margin-top:6px;">${t('coaPotenciaMsg')}</p></div>`;
  }
  COA_CONT_FIELDS.forEach(id => {
    const el = document.getElementById(id);
    if(!el) return;
    const isNd = el.value === 'nd';
    html += `<div style="background:var(--paper-raised); border-radius:6px; padding:12px 16px;"><div style="display:flex; justify-content:space-between; align-items:center;"><b>${t(COA_CONT_LABELS[id])}</b><span style="color:${isNd ? 'var(--moss-deep)' : 'var(--resin)'}; font-weight:600; font-family:'IBM Plex Mono',monospace; font-size:12px;">${isNd ? t('coaOptNd') : t('coaOptDet')}</span></div><p style="font-size:12.5px; color:var(--ink-soft); margin-top:6px;">${isNd ? t('coaNdMsg') : t('coaDetMsg')}</p></div>`;
  });
  resultEl.innerHTML = html;
}
['coaThc','coaCbd','coaPest','coaMetales','coaMicotox','coaSolv','coaMicrob'].forEach(id=>{
  const el = document.getElementById(id);
  if(el){ el.addEventListener('input', updateCoaTool); el.addEventListener('change', updateCoaTool); }
});
if(document.getElementById('coaPest')) updateCoaTool();

/* ===================== ESTIMADOR DE COSTOS INICIALES (rangos orientativos, no proyección real) ===================== */
const CI_CAPEX_PER_M2 = { indoor:[1600,3800], invernadero:[800,3000], outdoor:[100,250] };
const CI_OPEX_PER_M2_MES = { indoor:[30,70], invernadero:[15,40], outdoor:[5,15] };
const CI_TAMANO_M2 = { pequeno:[10,50], mediano:[100,300], grande:[500,2000] };
function updateCostoInicial(){
  const tipoEl = document.getElementById('ciTipo');
  const tamanoEl = document.getElementById('ciTamano');
  const resultEl = document.getElementById('ciResult');
  if(!tipoEl || !resultEl) return;
  const tipo = tipoEl.value;
  const tamano = tamanoEl.value;
  const [m2Min, m2Max] = CI_TAMANO_M2[tamano];
  const [capexMin, capexMax] = CI_CAPEX_PER_M2[tipo];
  const [opexMin, opexMax] = CI_OPEX_PER_M2_MES[tipo];
  const fmt = n => '$' + Math.round(n).toLocaleString('en-US');
  resultEl.innerHTML = `
    <div style="display:flex; justify-content:space-between;"><span>${t('ciCapexLabel')}</span><span style="color:var(--moss-deep); font-weight:600;">${fmt(m2Min*capexMin)} – ${fmt(m2Max*capexMax)}</span></div>
    <div style="display:flex; justify-content:space-between;"><span>${t('ciOpexLabel')}</span><span style="color:var(--moss-deep); font-weight:600;">${fmt(m2Min*opexMin)} – ${fmt(m2Max*opexMax)}/${t('ilLuzMesAbrev')}</span></div>
  `;
}
['ciTipo','ciTamano'].forEach(id=>{
  const el = document.getElementById(id);
  if(el){ el.addEventListener('input', updateCostoInicial); el.addEventListener('change', updateCostoInicial); }
});
if(document.getElementById('ciTipo')) updateCostoInicial();

