const TPL_LINKS = { tplInventarioLink:'inventario-basico', tplCostosLink:'calculadora-costos', tplChecklistLink:'checklist-primeros-pasos', tplCalendarioLink:'calendario-cumplimiento', tplSopLink:'plantillas-sop' };
