/* ===================== PREDICTOR DE CRUCES (locus B, de Meijer 2003; alelo nulo, Onofri et al. 2021) ===================== */
function getAlleles(type){
  if(type==='I') return ['T','T'];
  if(type==='III') return ['D','D'];
  if(type==='IV') return ['O','O'];
  return ['D','T'];
}
function classifyPair(x,y){
  const pair = [x,y].sort().join('');
  const map = {DD:'III', DO:'III', DT:'II', OO:'IV', OT:'I', TT:'I'};
  return map[pair];
}
function computeCross(){
  const p1 = document.getElementById('breedP1').value;
  const p2 = document.getElementById('breedP2').value;
  const a1 = getAlleles(p1), a2 = getAlleles(p2);
  const counts = {I:0, II:0, III:0, IV:0};
  a1.forEach(x=>{ a2.forEach(y=>{
    counts[classifyPair(x,y)]++;
  });});
  const colors = {I:'var(--moss-deep)', II:'var(--resin)', III:'var(--teal)', IV:'var(--clay)'};
  const labels = {I:'Tipo I', II:'Tipo II', III:'Tipo III', IV:'Tipo IV'};
  const resultEl = document.getElementById('breedResult');
  resultEl.innerHTML = '';
  ['I','II','III','IV'].forEach(t=>{
    const pct = Math.round(counts[t]/4*100);
    if(pct>0){
      const seg = document.createElement('div');
      seg.style.cssText = `background:${colors[t]}; flex:${pct}; padding:16px 8px; text-align:center; color:var(--paper); font-family:'IBM Plex Mono',monospace; font-size:12px;`;
      seg.innerHTML = `${labels[t]}<br><b style="font-size:16px;">${pct}%</b>`;
      resultEl.appendChild(seg);
    }
  });
  const notation = {I:'B_T/B_T', II:'B_D/B_T', III:'B_D/B_D', IV:'B_0/B_0'};
  document.getElementById('breedNote').textContent = `Cruce: ${notation[p1]} × ${notation[p2]} — fuente: de Meijer et al., 2003, Genetics; Onofri et al., 2021 (alelo nulo).`;
}
document.getElementById('breedP1')?.addEventListener('change', computeCross);
document.getElementById('breedP2')?.addEventListener('change', computeCross);
if(document.getElementById('breedP1')) computeCross();

/* ===================== BITÁCORA DE CULTIVO (Supabase, por cuenta) ===================== */
let lastBitEntries = [];
window.getBitEntries = function(){ return lastBitEntries; };
function renderBitacoraGate(){
  const gateEl = document.getElementById('bitAuthGate');
  const loggedInEl = document.getElementById('bitLoggedInOnly');
  if(!gateEl || !loggedInEl) return;
  const user = window.mvCurrentUser;
  gateEl.style.display = user ? 'none' : '';
  loggedInEl.style.display = user ? '' : 'none';
  const pdfBtn = document.getElementById('bitPdfBtn');
  const pdfLocked = document.getElementById('bitPdfLocked');
  if(pdfBtn) pdfBtn.style.display = (user && isPremium) ? 'inline-block' : 'none';
  if(pdfLocked) pdfLocked.style.display = (user && !isPremium) ? 'inline-flex' : 'none';
}
window.renderBitacoraGate = renderBitacoraGate;
async function loadBitEntries(){
  const listEl = document.getElementById('bitList');
  const resumenEl = document.getElementById('bitResumen');
  const graficoEl = document.getElementById('bitGrafico');
  if(!listEl) return;
  renderBitacoraGate();
  if(!window.mvCurrentUser) return;
  let entries = [];
  try{
    const { data, error } = await window.mvSupabase
      .from('bitacora_entries')
      .select('*')
      .eq('user_id', window.mvCurrentUser.id)
      .order('entry_date', { ascending: false });
    if(error) throw error;
    entries = (data || []).map(r => ({ id: r.id, fecha: r.entry_date, etapa: r.etapa, nota: r.nota, ph: r.ph, ec: r.ec, temp: r.temp, hum: r.hum, foto: r.foto_url }));
  }catch(e){ entries = []; }
  lastBitEntries = entries;
  if(entries.length===0){
    listEl.innerHTML = `<p class="bit-empty">${t('bitVacio')}</p>`;
    if(resumenEl) resumenEl.innerHTML = '';
    if(graficoEl) graficoEl.innerHTML = '';
    return;
  }
  entries.sort((a,b)=> new Date(b.fecha) - new Date(a.fecha));
  const sortedAsc = [...entries].sort((a,b)=> new Date(a.fecha) - new Date(b.fecha));

  // Panel resumen
  if(resumenEl){
    const primera = sortedAsc[0];
    const ultima = entries[0];
    let diasCiclo = '—';
    if(primera && primera.fecha){
      const dias = Math.floor((new Date() - new Date(primera.fecha)) / 86400000);
      if(!isNaN(dias) && dias >= 0) diasCiclo = dias;
    }
    resumenEl.innerHTML = `<div class="stat-row" style="margin:20px 0;">
      <div class="stat"><div class="n">${diasCiclo}</div><div class="l">${t('bitStatDias')}</div></div>
      <div class="stat"><div class="n">${entries.length}</div><div class="l">${t('bitStatEntradas')}</div></div>
      <div class="stat"><div class="n" style="font-size:15px;">${ultima.etapa || '—'}</div><div class="l">${t('bitStatEtapa')}</div></div>
    </div>`;
  }

  // Gráfico simple de pH y EC a lo largo del tiempo
  if(graficoEl){
    const conDatos = sortedAsc.filter(e => e.ph || e.ec);
    if(conDatos.length >= 2){
      const w = 600, h = 140, pad = 30;
      const phVals = conDatos.map(e => parseFloat(e.ph)).filter(v=>!isNaN(v));
      const ecVals = conDatos.map(e => parseFloat(e.ec)).filter(v=>!isNaN(v));
      const phMax = Math.max(...phVals, 7) + 0.5, phMin = Math.min(...phVals, 5) - 0.5;
      const ecMax = Math.max(...ecVals, 2) + 0.3, ecMin = 0;
      const stepX = (w - pad*2) / (conDatos.length - 1);
      const phPoints = conDatos.map((e,i) => {
        const v = parseFloat(e.ph); if(isNaN(v)) return null;
        const x = pad + i*stepX, y = h - pad - ((v-phMin)/(phMax-phMin))*(h-pad*2);
        return `${x},${y}`;
      }).filter(Boolean).join(' ');
      const ecPoints = conDatos.map((e,i) => {
        const v = parseFloat(e.ec); if(isNaN(v)) return null;
        const x = pad + i*stepX, y = h - pad - ((v-ecMin)/(ecMax-ecMin))*(h-pad*2);
        return `${x},${y}`;
      }).filter(Boolean).join(' ');
      graficoEl.innerHTML = `<div class="card-block" style="margin-top:8px;">
        <h3 style="font-size:15px;">${t('bitGraficoTitle')}</h3>
        <svg viewBox="0 0 ${w} ${h}" style="width:100%; height:auto; margin-top:8px;">
          <line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="var(--line-strong)" stroke-width="1"/>
          <polyline points="${phPoints}" fill="none" stroke="var(--teal)" stroke-width="2"/>
          <polyline points="${ecPoints}" fill="none" stroke="var(--resin)" stroke-width="2"/>
        </svg>
        <div style="display:flex; gap:16px; font-family:'IBM Plex Mono',monospace; font-size:10.5px; color:var(--ink-soft); margin-top:6px;">
          <span><span style="display:inline-block; width:10px; height:2px; background:var(--teal); vertical-align:middle;"></span> pH</span>
          <span><span style="display:inline-block; width:10px; height:2px; background:var(--resin); vertical-align:middle;"></span> EC</span>
        </div>
      </div>`;
    } else {
      graficoEl.innerHTML = `<div class="note-box" style="margin-top:8px;">${t('bitGraficoVacio')}</div>`;
    }
  }

  listEl.innerHTML = entries.map(e=>{
    const datos = [];
    if(e.ph) datos.push(`pH ${e.ph}`);
    if(e.ec) datos.push(`EC ${e.ec}`);
    if(e.temp) datos.push(`${e.temp}°C`);
    if(e.hum) datos.push(`${e.hum}% HR`);
    return `
    <div class="bit-entry">
      <div class="bit-entry-head">
        <span class="bit-entry-meta">${e.fecha || t('bitSinFecha')} · ${e.etapa}</span>
        <span class="bit-entry-del" onclick="deleteBitEntry('${e.id}')">${t('bitEliminar')}</span>
      </div>
      ${e.foto ? `<img src="${e.foto}" onclick="window.open('${e.foto}','_blank')" style="max-width:120px; border-radius:6px; border:1px solid var(--line-strong); display:block; margin-bottom:8px; cursor:pointer;">` : ''}
      ${datos.length ? `<div style="font-family:'IBM Plex Mono',monospace; font-size:10.5px; color:var(--teal); margin-bottom:4px;">${datos.join(' · ')}</div>` : ''}
      <div style="font-size:13.5px; color:var(--ink-soft);">${e.nota || t('bitSinNotas')}</div>
    </div>`;}).join('');
}
let currentBitFoto = null;
function handleBitFoto(input){
  const file = input.files && input.files[0];
  const previewEl = document.getElementById('bitFotoPreview');
  if(!file){ currentBitFoto = null; previewEl.innerHTML = ''; return; }
  const reader = new FileReader();
  reader.onload = function(ev){
    const img = new Image();
    img.onload = function(){
      const maxW = 700;
      const scale = Math.min(1, maxW / img.width);
      const canvas = document.createElement('canvas');
      canvas.width = img.width * scale;
      canvas.height = img.height * scale;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      currentBitFoto = canvas.toDataURL('image/jpeg', 0.7);
      previewEl.innerHTML = `<img src="${currentBitFoto}" style="max-width:160px; border-radius:6px; border:1px solid var(--line-strong); display:block;">`;
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
}
async function addBitEntry(){
  if(!window.mvCurrentUser) return;
  const fecha = document.getElementById('bitFecha').value;
  const etapa = document.getElementById('bitEtapa').value;
  const nota = document.getElementById('bitNota').value.trim();
  const ph = document.getElementById('bitPh').value;
  const ec = document.getElementById('bitEc').value;
  const temp = document.getElementById('bitTemp').value;
  const hum = document.getElementById('bitHum').value;
  const statusEl = document.getElementById('bitStatus');
  if(!nota){ statusEl.textContent = t('bitErrSinNota'); return; }
  try{
    const { error } = await window.mvSupabase.from('bitacora_entries').insert({
      user_id: window.mvCurrentUser.id,
      entry_date: fecha || null,
      etapa, nota,
      ph: ph || null, ec: ec || null, temp: temp || null, hum: hum || null,
      foto_url: currentBitFoto
    });
    if(error) throw error;
    statusEl.textContent = t('bitGuardadoOk');
    document.getElementById('bitNota').value = '';
    document.getElementById('bitPh').value = '';
    document.getElementById('bitEc').value = '';
    document.getElementById('bitTemp').value = '';
    document.getElementById('bitHum').value = '';
    document.getElementById('bitFotoInput').value = '';
    document.getElementById('bitFotoPreview').innerHTML = '';
    currentBitFoto = null;
    loadBitEntries();
  }catch(e){ statusEl.textContent = t('bitErrGuardar'); }
}
async function deleteBitEntry(id){
  if(!window.mvCurrentUser) return;
  try{
    const { error } = await window.mvSupabase.from('bitacora_entries').delete().eq('id', id);
    if(error) throw error;
    loadBitEntries();
  }catch(e){}
}

/* ===================== REGISTRO DE TRICOMAS (conectado a bitacora_entries) ===================== */
function renderTrichLogGate(){
  const gateEl = document.getElementById('trichLogGate');
  const loggedInEl = document.getElementById('trichLogLoggedIn');
  if(!gateEl || !loggedInEl) return;
  const user = window.mvCurrentUser;
  gateEl.style.display = user ? 'none' : '';
  loggedInEl.style.display = user ? '' : 'none';
}
window.renderTrichLogGate = renderTrichLogGate;
async function addTrichLogEntry(){
  if(!window.mvCurrentUser) return;
  const fecha = document.getElementById('trichLogFecha').value;
  const clear = document.getElementById('trichLogClear').value;
  const milky = document.getElementById('trichLogMilky').value;
  const amber = document.getElementById('trichLogAmber').value;
  const statusEl = document.getElementById('trichLogStatus');
  if(!fecha || (!clear && !milky && !amber)){ statusEl.textContent = t('trichLogErrDatos'); return; }
  try{
    const { error } = await window.mvSupabase.from('bitacora_entries').insert({
      user_id: window.mvCurrentUser.id,
      entry_date: fecha,
      etapa: t('trichLogEtapaTag'),
      nota: t('trichLogNotaAuto'),
      trich_clear: clear || null,
      trich_milky: milky || null,
      trich_amber: amber || null
    });
    if(error) throw error;
    statusEl.textContent = t('trichLogGuardadoOk');
    document.getElementById('trichLogClear').value = '';
    document.getElementById('trichLogMilky').value = '';
    document.getElementById('trichLogAmber').value = '';
    loadTrichLog();
    if(document.getElementById('bitacora')?.classList.contains('active')) loadBitEntries();
  }catch(e){ statusEl.textContent = t('trichLogErrGuardar'); }
}
window.addTrichLogEntry = addTrichLogEntry;
async function loadTrichLog(){
  const chartEl = document.getElementById('trichLogChart');
  if(!chartEl) return;
  renderTrichLogGate();
  if(!window.mvCurrentUser) return;
  let entries = [];
  try{
    const { data, error } = await window.mvSupabase
      .from('bitacora_entries')
      .select('entry_date, trich_clear, trich_milky, trich_amber')
      .eq('user_id', window.mvCurrentUser.id)
      .not('trich_clear', 'is', null)
      .order('entry_date', { ascending: true });
    if(error) throw error;
    entries = (data || []).filter(e => e.entry_date);
  }catch(e){ entries = []; }
  if(entries.length < 2){
    chartEl.innerHTML = `<div class="note-box">${t('trichLogChartVacio')}</div>`;
    return;
  }
  const w = 600, h = 140, pad = 30;
  const stepX = (w - pad*2) / (entries.length - 1);
  const scaleY = v => h - pad - (v/100)*(h-pad*2);
  const line = (key, color) => {
    const pts = entries.map((e,i) => {
      const v = parseFloat(e[key]); if(isNaN(v)) return null;
      return `${pad + i*stepX},${scaleY(v)}`;
    }).filter(Boolean).join(' ');
    return `<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2"/>`;
  };
  chartEl.innerHTML = `<div class="card-block" style="margin-top:0;">
    <h3 style="font-size:15px;">${t('trichLogChartTitle')}</h3>
    <svg viewBox="0 0 ${w} ${h}" style="width:100%; height:auto; margin-top:8px;">
      <line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="var(--line-strong)" stroke-width="1"/>
      ${line('trich_clear','var(--ink-soft)')}
      ${line('trich_milky','var(--teal)')}
      ${line('trich_amber','var(--resin)')}
    </svg>
    <div style="display:flex; gap:16px; font-family:'IBM Plex Mono',monospace; font-size:10.5px; color:var(--ink-soft); margin-top:6px; flex-wrap:wrap;">
      <span><span style="display:inline-block; width:10px; height:2px; background:var(--ink-soft); vertical-align:middle;"></span> ${t('trichVisClear')}</span>
      <span><span style="display:inline-block; width:10px; height:2px; background:var(--teal); vertical-align:middle;"></span> ${t('trichVisMilky')}</span>
      <span><span style="display:inline-block; width:10px; height:2px; background:var(--resin); vertical-align:middle;"></span> ${t('trichVisAmber')}</span>
    </div>
  </div>`;
}
window.loadTrichLog = loadTrichLog;
if(document.getElementById('trichLogGate')){ renderTrichLogGate(); loadTrichLog(); }

/* ===================== CHECKLIST PRE-VIAJE ===================== */
const travelChecklistItems = [
  'Verifiqué el estatus legal de mi destino en el explorador',
  'Verifiqué el estatus del CBD por separado — no asumo que va incluido',
  'Revisé si mi vuelo tiene escala en un país con ley distinta',
  'No llevo ningún producto conmigo, ni de ida ni de vuelta',
  'Guardé copia de mi documentación médica, si mi viaje es por uso medicinal',
  'Verifiqué también el estatus del país al que regreso'
];
function renderTravelChecklist(){
  const el = document.getElementById('travelChecklist');
  if(!el || el.dataset.built) { updateChecklistProgress(); return; }
  el.innerHTML = travelChecklistItems.map((item,i)=>`
    <label style="display:flex; align-items:flex-start; gap:10px; padding:9px 0; border-top:1px solid var(--line); font-size:13px; color:var(--ink-soft); cursor:pointer;">
      <input type="checkbox" class="tc-item" data-idx="${i}" style="margin-top:3px;">
      <span>${item}</span>
    </label>`).join('');
  el.dataset.built = '1';
  el.querySelectorAll('.tc-item').forEach(cb=> cb.addEventListener('change', updateChecklistProgress));
  updateChecklistProgress();
}
function updateChecklistProgress(){
  const boxes = document.querySelectorAll('.tc-item');
  const checked = document.querySelectorAll('.tc-item:checked').length;
  const progEl = document.getElementById('travelChecklistProgress');
  if(progEl) progEl.textContent = `${checked} de ${boxes.length} verificados` + (checked===boxes.length && boxes.length>0 ? ' — ✓ listo para viajar' : '');
}

/* ===================== CHECKLIST DE COSECHA (tricomas) ===================== */
function getTrichomeOptions(){
  return [
    {v:'clear', label:t('trClearLabel'), verdict:t('trClearVerdict')},
    {v:'milky', label:t('trMilkyLabel'), verdict:t('trMilkyVerdict')},
    {v:'mix', label:t('trMixLabel'), verdict:t('trMixVerdict')},
    {v:'amber', label:t('trAmberLabel'), verdict:t('trAmberVerdict')}
  ];
}
function renderHarvestChecklist(){
  const el = document.getElementById('harvestChecklist');
  if(!el) return;
  const opts = getTrichomeOptions();
  const prevChecked = el.querySelector('.trich-radio:checked')?.value;
  el.innerHTML = opts.map(o=>`
    <label style="display:flex; align-items:center; gap:10px; padding:8px 0; border-top:1px solid var(--line); font-size:13px; color:var(--ink-soft); cursor:pointer;">
      <input type="radio" name="trich" value="${o.v}" class="trich-radio" ${o.v===prevChecked?'checked':''}>
      <span>${o.label}</span>
    </label>`).join('');
  el.querySelectorAll('.trich-radio').forEach(r=> r.addEventListener('change', ()=>{
    const chosen = getTrichomeOptions().find(o=>o.v===r.value);
    const verdictEl = document.getElementById('harvestVerdict');
    verdictEl.textContent = chosen.verdict;
    verdictEl.style.color = chosen.v==='clear' ? 'var(--resin)' : chosen.v==='amber' ? 'var(--resin)' : 'var(--moss-deep)';
  }));
  if(prevChecked){
    const verdictEl = document.getElementById('harvestVerdict');
    const chosen = opts.find(o=>o.v===prevChecked);
    if(verdictEl && chosen) verdictEl.textContent = chosen.verdict;
  }
}

/* ===================== SELECTOR VISUAL DE SÍNTOMAS ===================== */
function renderSymptomPicker(){
  const picker = document.getElementById('symptomPicker');
  if(!picker || picker.dataset.built) return;
  picker.dataset.built = '1';
  picker.querySelectorAll('.chip').forEach(chip=>{
    chip.onclick = ()=>{
      const match = chip.dataset.match;
      const cards = document.querySelectorAll('#diagGrid .diag-card');
      let target = null;
      cards.forEach(c=>{
        c.classList.remove('diag-highlight');
        const h4 = c.querySelector('h4');
        if(h4 && h4.textContent.includes(match)) target = c;
      });
      if(target){
        target.classList.add('diag-highlight');
        target.scrollIntoView({behavior:'smooth', block:'center'});
      }
    };
  });
}

/* Run once on load so the initial render always matches translations[currentLang],
   not just index.html's inline Spanish — keeps static/dynamic content from drifting
   apart again like it did earlier in this project. */
applyLang();

/* ===================== BRILLO NEÓN: CURSOR (escritorio) ===================== */
(function initCursorGlow(){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  if(!window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;

  const glow = document.createElement('div');
  glow.className = 'cursor-glow';
  glow.setAttribute('aria-hidden', 'true');
  document.body.appendChild(glow);

  let targetX = 0, targetY = 0, raf = null, hideTimer = null;

  function render(){
    glow.style.transform = `translate3d(${targetX}px, ${targetY}px, 0)`;
    raf = null;
  }

  window.addEventListener('pointermove', (e)=>{
    if(e.pointerType && e.pointerType !== 'mouse') return;
    targetX = e.clientX; targetY = e.clientY;
    glow.classList.add('is-active');
    if(!raf) raf = requestAnimationFrame(render);
    clearTimeout(hideTimer);
    hideTimer = setTimeout(()=> glow.classList.remove('is-active'), 1200);
  }, {passive:true});

  window.addEventListener('blur', ()=> glow.classList.remove('is-active'));
})();

/* ===================== BRILLO NEÓN: TOUCH (móvil) ===================== */
(function initTouchGlow(){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  if(!window.matchMedia('(pointer: coarse)').matches) return;

  document.addEventListener('touchstart', (e)=>{
    for(const touch of e.changedTouches){
      const ripple = document.createElement('div');
      ripple.className = 'touch-ripple';
      ripple.setAttribute('aria-hidden', 'true');
      ripple.style.left = touch.clientX + 'px';
      ripple.style.top = touch.clientY + 'px';
      document.body.appendChild(ripple);
      ripple.addEventListener('animationend', ()=> ripple.remove(), {once:true});
    }
  }, {passive:true});
})();

/* ===================== EASTER EGG: MINI CIENTÍFICO ===================== */
(function initMiniScientist(){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const STORE_KEY = 'mv_scientist_state';
  const FIRST_MS = 120000;       // 2 min de uso activo
  const REPEAT_MS = 960000;      // 16 min de uso activo
  const TICK_MS = 5000;          // resolución del contador

  function loadState(){
    try{
      const raw = sessionStorage.getItem(STORE_KEY);
      if(raw) return JSON.parse(raw);
    }catch(e){}
    return { activeMs: 0, targetMs: FIRST_MS };
  }
  function saveState(state){
    try{ sessionStorage.setItem(STORE_KEY, JSON.stringify(state)); }catch(e){}
  }

  const state = loadState();

  function createMiniScientist(){
    const wrap = document.createElement('div');
    wrap.className = 'mini-scientist';
    wrap.setAttribute('aria-hidden', 'true');
    wrap.innerHTML = '<svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg">'
      + '<g class="ms-bob">'
      + '<ellipse cx="10" cy="46" rx="7" ry="3" fill="var(--moss-deep)" opacity="0.35"/>'
      + '<ellipse cx="18" cy="40" rx="5" ry="2.4" fill="var(--moss-deep)" opacity="0.5"/>'
      + '<path d="M26 24 Q34 20 40 30 Q42 40 34 48 Q26 52 20 46 Q16 36 26 24 Z" fill="var(--moss)" opacity="0.92"/>'
      + '<path d="M26 24 Q34 20 40 30 Q42 40 34 48" fill="none" stroke="var(--moss-deep)" stroke-width="1.2" opacity="0.6"/>'
      + '<circle cx="40" cy="24" r="9" fill="var(--paper-raised)" stroke="var(--line-strong)" stroke-width="1"/>'
      + '<circle cx="37" cy="23" r="2.6" fill="var(--teal)" opacity="0.9"/>'
      + '<circle cx="43" cy="23" r="2.6" fill="var(--teal)" opacity="0.9"/>'
      + '<path d="M35 20 Q40 17 45 20" fill="none" stroke="var(--ink-soft)" stroke-width="1"/>'
      + '<path d="M32 30 Q40 34 48 28" fill="none" stroke="var(--ink)" stroke-width="2" stroke-linecap="round"/>'
      + '</g></svg>';
    return wrap;
  }

  function spawnSmokePuff(el){
    const rect = el.getBoundingClientRect();
    const puff = document.createElement('div');
    puff.className = 'ms-smoke';
    puff.setAttribute('aria-hidden', 'true');
    puff.style.left = (rect.left + rect.width * 0.18) + 'px';
    puff.style.top = (rect.top + rect.height * 0.62) + 'px';
    document.body.appendChild(puff);
    requestAnimationFrame(()=> puff.classList.add('is-fading'));
    puff.addEventListener('animationend', ()=> puff.remove(), {once:true});
  }

  function flyAcross(){
    const el = createMiniScientist();
    el.style.top = (14 + Math.random() * 30) + '%';
    document.body.appendChild(el);
    requestAnimationFrame(()=> el.classList.add('is-flying'));
    const smokeTimer = setInterval(()=> spawnSmokePuff(el), 220);
    el.addEventListener('animationend', ()=>{ clearInterval(smokeTimer); el.remove(); }, {once:true});
  }

  setInterval(()=>{
    if(document.visibilityState !== 'visible') return;
    state.activeMs += TICK_MS;
    if(state.activeMs >= state.targetMs){
      flyAcross();
      state.activeMs = 0;
      state.targetMs = REPEAT_MS;
    }
    saveState(state);
  }, TICK_MS);
})();
